function gnth(a1, r, n){ return a1*Math.pow(r, n-1); }
function gsum(a1, r, n){ if(r===1) return a1*n; return a1*(1-Math.pow(r,n))/(1-r); }
var EXPORTS = { gnth:gnth, gsum:gsum };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GeometricForgePure = EXPORTS; }
